/* Local, progressively enhanced 3D vignettes and entrance choreography. */
(()=>{
const root=document.documentElement;let paused=matchMedia('(prefers-reduced-motion:reduce)').matches;try{paused=paused||localStorage.getItem('darna_motion_paused')==='1'}catch{}root.classList.toggle('motion-paused',paused);
const labels={fr:{pause:'Mettre les animations en pause',play:'Reprendre les animations',lantern:'Lumière de la maison · 3D',tea:'Le rituel du thé · 3D',disc:'MARHBA BIKOM'},en:{pause:'Pause animations',play:'Resume animations',lantern:'Light of the house · 3D',tea:'The tea ritual · 3D',disc:'YOU ARE HOME'},ar:{pause:'إيقاف الحركة مؤقتًا',play:'استئناف الحركة',lantern:'نور الدار · ثلاثي الأبعاد',tea:'طقوس الشاي · ثلاثي الأبعاد',disc:'مرحبا بكم'}};
const curtain=document.createElement('div');curtain.className='motion-curtain';curtain.setAttribute('aria-hidden','true');curtain.innerHTML='<b>Darna Food</b><span>MARHBA BIKOM</span><i></i>';if(!paused)document.body.append(curtain);setTimeout(()=>curtain.remove(),1500);
const art=document.querySelector('.hero-art');art.insertAdjacentHTML('beforeend','<div class="hero-orbit" aria-hidden="true"></div><figure class="object-stage hero-lantern"><canvas tabindex="0" role="img"></canvas><figcaption></figcaption></figure>');
document.querySelector('.story').insertAdjacentHTML('beforeend','<figure class="object-stage story-tea"><canvas tabindex="0" role="img"></canvas><figcaption></figcaption></figure>');
document.querySelector('#resa .grid>div').insertAdjacentHTML('beforeend','<div class="reservation-disc" aria-hidden="true"><div class="disc">دارنا<small></small></div></div>');
const switcher=document.createElement('button');switcher.className='motion-switch';document.body.append(switcher);let resumeObjects=[];
function text(){const l=labels[L];switcher.textContent=paused?l.play:l.pause;switcher.setAttribute('aria-pressed',String(paused));const lanternCaption=document.querySelector('.hero-lantern figcaption');if(lanternCaption)lanternCaption.textContent=l.lantern;document.querySelector('.story-tea figcaption').textContent=l.tea;document.querySelector('.disc small').textContent=l.disc;document.querySelectorAll('.object-stage canvas').forEach(c=>c.setAttribute('aria-label',(c.closest('.hero-lantern')?l.lantern:l.tea)+' ↔'));
 const title=document.querySelector('.hero h1'),words=title.textContent.trim().split(/\s+/);title.setAttribute('aria-label',title.textContent);title.replaceChildren(...words.flatMap((word,i)=>{const clip=document.createElement('span');clip.className='word-clip';clip.setAttribute('aria-hidden','true');const span=document.createElement('span');span.className='word';span.style.setProperty('--word',i);span.textContent=word;clip.append(span);return i?[document.createTextNode(' '),clip]:[clip]}));decorate();}
switcher.onclick=()=>{paused=!paused;root.classList.toggle('motion-paused',paused);try{localStorage.setItem('darna_motion_paused',paused?'1':'0')}catch{}switcher.textContent=paused?labels[L].play:labels[L].pause;switcher.setAttribute('aria-pressed',String(paused));resumeObjects.forEach(f=>f());document.dispatchEvent(new Event("darna-motion-change"))};
const previousLanguage=setLang;setLang=function(l){previousLanguage(l);text()};const previousRender=render;render=function(){previousRender();decorate()};
const fine=matchMedia('(pointer:fine)').matches;function decorate(){document.querySelectorAll('.sig article,.ritual-grid article,.gal button').forEach(el=>{if(el.dataset.depthReady)return;el.dataset.depthReady='1';el.classList.add('depth-card');if(!fine)return;el.addEventListener('pointermove',e=>{if(paused)return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(1000px) rotateY(${x*13}deg) rotateX(${-y*10}deg) translateY(-5px)`});el.addEventListener('pointerleave',()=>el.style.transform='')})}text();
const watch=new IntersectionObserver(entries=>entries.forEach(e=>{e.target.classList.toggle('is-in-view',e.isIntersecting);e.target.classList.toggle('out-of-view',!e.isIntersecting)}),{threshold:.05});document.querySelectorAll('.story,.reservation-disc,.hero-orbit').forEach(el=>watch.observe(el));
// Low-overhead 3D mesh renderer. No GPU requirement, network request or library.
function vignette(selector,type){const canvas=document.querySelector(selector),box=canvas.parentElement,ctx=canvas.getContext('2d');let width=0,height=0,angle=.5,pitch=.15,frame=null,visible=false,drag=null,last=0;const faces=[];
function lathe(profile,color,metal=false,segments=48){for(let row=0;row<profile.length-1;row++)for(let i=0;i<segments;i++){const a=i/segments*Math.PI*2,b=(i+1)/segments*Math.PI*2;const[r,y]=profile[row],[r2,y2]=profile[row+1];faces.push({points:[[r*Math.cos(a),y,r*Math.sin(a)],[r*Math.cos(b),y,r*Math.sin(b)],[r2*Math.cos(b),y2,r2*Math.sin(b)],[r2*Math.cos(a),y2,r2*Math.sin(a)]],color,metal})}}
function panel(a){const r=.65,ys=[-.58,.67],d=.16;const points=[[r*Math.cos(a-d),ys[0],r*Math.sin(a-d)],[r*Math.cos(a+d),ys[0],r*Math.sin(a+d)],[r*Math.cos(a+d),ys[1],r*Math.sin(a+d)],[r*Math.cos(a-d),ys[1],r*Math.sin(a-d)]];faces.push({points,color:[184,140,66],metal:true});for(const y of [-.25,.1,.45]){const r2=.66;faces.push({points:[[r2*Math.cos(a-.2),y-.025,r2*Math.sin(a-.2)],[r2*Math.cos(a+.2),y-.025,r2*Math.sin(a+.2)],[r2*Math.cos(a+.2),y+.025,r2*Math.sin(a+.2)],[r2*Math.cos(a-.2),y+.025,r2*Math.sin(a-.2)]],color:[211,174,100],metal:true})}}
const gold=[173,130,63],green=[26,87,66],cream=[220,211,180];
if(type==='lantern'){lathe([[0,-.85],[.35,-.85],[.5,-.7],[.66,-.6],[.68,-.53],[.64,-.48]],gold,true);lathe([[.64,.65],[.69,.71],[.62,.79],[.46,.93],[.3,1.08],[.12,1.15],[0,1.15]],gold,true);lathe([[0,1.15],[.1,1.15],[.12,1.24],[.08,1.28],[0,1.28]],gold,true);lathe([[0,-.5],[.35,-.5],[.4,.5],[0,.5]],[215,154,65]);for(let i=0;i<8;i++)panel(i/8*Math.PI*2);lathe([[.1,1.26],[.13,1.34],[.1,1.43],[.04,1.46],[0,1.43]],gold,true)}else{lathe([[0,-.7],[.65,-.7],[.95,-.65],[1.06,-.58],[1.05,-.54],[.85,-.58],[0,-.6]],gold,true);lathe([[0,-.58],[.35,-.58],[.42,-.5],[.49,.68],[.52,.72],[.52,.77],[.46,.77],[.43,.68],[.37,-.43],[0,-.43]],green);lathe([[.5,.68],[.52,.7],[.53,.74],[.52,.77],[.5,.77]],gold,true);lathe([[.39,-.38],[.42,-.3],[.47,.48],[.44,.5]],gold,true);for(const y of [-.15,.02,.19,.36])lathe([[.44+y*.04,y],[.445+y*.04,y+.012]],cream,true);lathe([[0,.49],[.45,.49],[.45,.51],[0,.51]],[101,70,24]);}
function project(p){let[x,y,z]=p;const xx=x*Math.cos(angle)+z*Math.sin(angle),zz=-x*Math.sin(angle)+z*Math.cos(angle);return[xx,y*Math.cos(pitch)-zz*Math.sin(pitch),y*Math.sin(pitch)+zz*Math.cos(pitch)]}
function request(){if(!frame)frame=requestAnimationFrame(draw)}
function draw(t){frame=null;if(!visible||document.hidden)return;const delta=Math.min((t-last)/1000,.05);last=t;if(!paused&&!drag)angle+=delta*.25;ctx.clearRect(0,0,width,height);const scale=Math.min(width/(type==='tea'?2.7:2.3),height/3.1),cy=height*.52;const glow=ctx.createRadialGradient(width*.48,height*.5,0,width*.48,height*.5,width*.5);glow.addColorStop(0,type==='lantern'?'#eab55d25':'#ddcba50f');glow.addColorStop(1,'#ddcba500');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);const items=faces.map(f=>({f,p:f.points.map(project)})).sort((a,b)=>a.p.reduce((s,v)=>s+v[2],0)-b.p.reduce((s,v)=>s+v[2],0));for(const{f,p}of items){const a=p[1].map((v,i)=>v-p[0][i]),b=p[3].map((v,i)=>v-p[0][i]);let n=[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],len=Math.hypot(...n)||1;n=n.map(v=>-v/len);const diffuse=Math.max(0,-n[0]*.45+n[1]*.5+n[2]*.7),spec=Math.pow(Math.max(0,-n[0]*.4+n[1]*.2+n[2]*.9),f.metal?22:42);ctx.fillStyle=`rgb(${f.color.map(c=>Math.round(Math.min(255,c*(.55+diffuse*.65)+spec*(f.metal?110:60)))).join(',')})`;ctx.beginPath();p.forEach(([x,y,z],i)=>{const perspective=5/(5-z*.16),px=width/2+x*scale*perspective,py=cy-y*scale*perspective; i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.closePath();ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.3;ctx.stroke()}
if(type==='tea'&&!paused){ctx.save();ctx.strokeStyle='#f4e4bc55';ctx.lineWidth=1;for(let i=0;i<3;i++){const x=width/2+(i-1)*12,shift=Math.sin(t/1500+i)*5;ctx.beginPath();ctx.moveTo(x,cy-scale*.6);ctx.bezierCurveTo(x+15+shift,cy-scale*.85,x-15+shift,cy-scale*.95,x+shift,cy-scale*1.1);ctx.stroke()}ctx.restore()}if(!paused)request()}
new ResizeObserver(()=>{width=box.clientWidth;height=box.clientHeight;const d=Math.min(devicePixelRatio,1.5);canvas.width=width*d;canvas.height=height*d;ctx.setTransform(d,0,0,d,0,0);request()}).observe(box);new IntersectionObserver(e=>{visible=e[0].isIntersecting;if(visible){last=performance.now();request()}}).observe(box);resumeObjects.push(request);canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,angle};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag){angle=drag.angle+(e.clientX-drag.x)*.015;request()}});for(const evt of ['pointerup','pointercancel'])canvas.addEventListener(evt,()=>{drag=null;request()});canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();angle+=e.key==='ArrowRight'?.15:-.15;request()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){last=performance.now();request()}})}
vignette('.hero-lantern canvas','lantern');vignette('.story-tea canvas','tea');
})();
